CREATE PROCEDURE sp_rpt_Toast_Net_Sales_Validation -- Add the parameters for the stored procedure here 	( 		@StartDate date = null, 		@EndDate date = null, 		@StoreGrouping int = 9, 		@StoreGroup varchar(1500) = '243' 	) AS /** ## Procedure Name       *[toast].[dbo].[sp_rpt_Toast_Net_Sales_Validation]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20260113   **Report Name**         *Toast Net Sales Validation*   **Summary**   *Compares Toast Web reported net sales to the Royalty Net used for Flash report*      ### Parameters   ```sql   StartDate date              Start date of the range   EndDate date                End Date of the range   StoreGrouping int           The grouping type of stores   StoreGroup varchar(1500)    The store / store group / dma / etc to run for   ```      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;                  DECLARE @SDate date         DECLARE @EDate date          SET @SDate =              CASE                 WHEN @StartDate IS NULL THEN convert(date,getdate()-14)                 ELSE @StartDate             END          SET @EDate =             CASE                 WHEN @EndDate IS NULL THEN convert(date,getdate()-1)                 ELSE @EndDate             END  		declare @Params varchar(2000) = (select @StoreGrouping as StoreGrouping, @StoreGroup as StoreGroup, @SDate as SDate, @EDate as EDate for json path)          select *         into #StoresIncluded         from dev_aloha.dbo.get_StoresIncluded (@StoreGrouping, @StoreGroup, @EDate)      	create table #Results         (             DateOfBusiness date             , RestaurantID int             , RestaurantName varchar(100)             , ToastNet decimal(12,2)             , ToastRefunds decimal(12,2)             , ToastVoids decimal(12,2)             , CalculatedNet decimal(12,2)             , CalculatedSvcChg decimal(12,2)         )          select               s.businessDate             , r.StoreID             , r.StoreName             , isnull(sum(s.netSalesAmount),0) NetSales             , isnull(sum(s.refundAmount), 0) Refunds             , isnull(sum(s.voidOrdersAmount), 0) Voids         into #ToastNet         from toast.dbo.Analytics_Sales s  with (NOLOCK)         join #StoresIncluded r         on s.restaurantGuid = r.StoreGUID         where businessDate between @SDate and @EDate         and s.businessDate >= r.ToastLive         group by s.businessDate, r.StoreID, r.StoreName          insert into #Results (DateOfBusiness, RestaurantID, RestaurantName, ToastNet, ToastRefunds, ToastVoids)         select             businessDate, StoreID, StoreName, NetSales, Refunds, Voids         from #ToastNet          select                s.DateOfBusiness             , s.StoreNum             , isnull(sum(ChargeAmount), 0) SvcChgs         into #SvcChgs         from toast.dbo.hstServiceCharges s  with (NOLOCK)         join toast.dbo.hstCheck c         on s.CheckID = c.CheckID         join #StoresIncluded si         on s.StoreNum = si.StoreID         where s.DateOfBusiness between @SDate and @EDate         and s.DateOfBusiness >= si.ToastLive         and c.Voided = 0         group by s.DateOfBusiness, s.StoreNum          update #Results set             CalculatedSvcChg = s.SvcChgs         from #Results r         join #SvcChgs s         on r.RestaurantID = s.StoreNum         and r.DateOfBusiness = s.DateOfBusiness          /*select             DateOfBusiness             , RestaurantID             , sum(NetSales) NetSales         into #Net         from dev_aloha.dbo.tbl_SalesDataByDayPart sddp  with (NOLOCK)         join #StoresIncluded si         on sddp.RestaurantID = si.StoreID         where DateOfBusiness between @SDate and @EDate         and sddp.DateOfBusiness >= si.ToastLive         group by DateOfBusiness, RestaurantID */          select                i.DateOfBusiness             , i.StoreNum as RestaurantID             , si.ToastLive             , si.StoreName             , sum(i.DiscPric) as NetSales         into #Net         from toast.dbo.hstItem i with (NOLOCK)         join #StoresIncluded si         on i.StoreNum = si.StoreID         where i.DateOfBusiness between @SDate and @EDate         and i.DateOfBusiness >= si.ToastLive         and i.Deferred = 0         and i.Voided = 0         and i.ModificationID = '0'         group by i.DateOfBusiness, i.StoreNum , si.ToastLive, si.StoreName         order by dateofbusiness desc, ToastLive, StoreName           update #Results set             CalculatedNet = n.NetSales         from #Results r         join #Net n         on r.DateOfBusiness = n.DateOfBusiness         and r.RestaurantID = n.RestaurantID          select              r.DateOfBusiness             , r.RestaurantID             , r.RestaurantName             , isnull(ToastNet,0) ToastNet             , '' as BlankCol1             , isnull(CalculatedNet, 0) CalculatedNet             , isnull(CalculatedSvcChg, 0) CalculatedSvcChg             , isnull(ToastRefunds, 0) ToastRefunds             --, isnull(ToastVoids, 0) ToastVoids             , '' as BlankCol2             , isnull(ToastNet,0) - isnull(CalculatedNet,0) - isnull(CalculatedSvcChg,0) + isnull(ToastRefunds,0) as 'Difference'         from #Results r         join #StoresIncluded si         on r.RestaurantID = si.StoreID         --where (isnull(ToastNet,0) - isnull(CalculatedNet,0) - isnull(CalculatedSvcChg,0) + isnull(ToastRefunds,0)) != 0         order by DateOfBusiness, StoreID          drop table #StoresIncluded         drop table #SvcChgs         drop table #Net         drop table #Results         drop table #ToastNet                   -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END